// ❌ Leak: every request-scoped hub is rooted by the static bus forever
public class NotificationBus
{
    public static event EventHandler<Notification> Sent;   // static event
    public void Send(Notification n) => Sent?.Invoke(this, n);
}

public class AuditHub : IDisposable
{
    public AuditHub() => NotificationBus.Sent += OnSent;
    private void OnSent(object s, Notification n) { /* audit */ }
    public void Dispose() { }   // forgot: unsubscribe!
}
// Each transient AuditHub stays alive forever -> heap grows per request.

// ✅ Fix: symmetric subscribe/unsubscribe
public class AuditHub : IDisposable
{
    public AuditHub() => NotificationBus.Sent += OnSent;
    private void OnSent(object s, Notification n) { /* audit */ }
    public void Dispose() => NotificationBus.Sent -= OnSent;
}

